let i18nUiObserver = null;
let i18nUiBusy = false;

function translateUiTextNode(node, lang) {
    // Hat die Spiellogik den Text inzwischen selbst geändert, gilt das gemerkte Original nicht mehr.
    if (node.__i18nDe !== undefined && node.nodeValue !== node.__i18nEn) { delete node.__i18nDe; delete node.__i18nEn; }
    if (lang === 'en') {
        const raw = node.__i18nDe !== undefined ? node.__i18nDe : node.nodeValue;
        const key = raw.trim().replace(/\s+/g, ' ');
        const en = key && I18N_UI_EN[key];
        if (!en || en === key) return;
        const neu = raw.replace(raw.trim(), en);
        node.__i18nDe = raw;
        node.__i18nEn = neu;
        if (node.nodeValue !== neu) node.nodeValue = neu;
    } else if (node.__i18nDe !== undefined) {
        const de = node.__i18nDe;
        delete node.__i18nDe;
        delete node.__i18nEn;
        if (node.nodeValue !== de) node.nodeValue = de;
    }
}

function translateUiAttributes(el, lang) {
    ['title', 'placeholder'].forEach(attr => {
        const store = '__i18n_' + attr;
        if (lang === 'en') {
            const raw = el[store] !== undefined ? el[store] : el.getAttribute(attr);
            const en = raw && I18N_UI_EN[raw.trim()];
            if (en) { el[store] = raw; el.setAttribute(attr, en); }
        } else if (el[store] !== undefined) {
            el.setAttribute(attr, el[store]);
            delete el[store];
        }
    });
}

function translateUiSubtree(root, lang) {
    if (!root) return;
    if (root.nodeType === 3) { translateUiTextNode(root, lang); return; }
    if (root.nodeType !== 1 || root.tagName === 'SCRIPT' || root.tagName === 'STYLE') return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
        acceptNode: n => (n.nodeType === 1 && (n.tagName === 'SCRIPT' || n.tagName === 'STYLE')) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT
    });
    if (root.hasAttribute && (root.hasAttribute('title') || root.hasAttribute('placeholder'))) translateUiAttributes(root, lang);
    let n;
    while ((n = walker.nextNode())) {
        if (n.nodeType === 3) translateUiTextNode(n, lang);
        else if (n.hasAttribute('title') || n.hasAttribute('placeholder')) translateUiAttributes(n, lang);
    }
}

// Aus setLanguage(): ganze Oberfläche umstellen und neue Inhalte weiter übersetzen.
function applyUiTranslation(lang) {
    if (typeof document === 'undefined' || !document.body) return;
    i18nUiBusy = true;
    translateUiSubtree(document.body, lang);
    i18nUiBusy = false;
    if (lang === 'en' && !i18nUiObserver && typeof MutationObserver !== 'undefined') {
        i18nUiObserver = new MutationObserver(records => {
            if (i18nUiBusy) return;
            i18nUiBusy = true;
            records.forEach(r => {
                if (r.type === 'characterData') translateUiTextNode(r.target, 'en');
                else r.addedNodes.forEach(n => translateUiSubtree(n, 'en'));
            });
            i18nUiBusy = false;
        });
        i18nUiObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
    } else if (lang !== 'en' && i18nUiObserver) {
        i18nUiObserver.disconnect();
        i18nUiObserver = null;
    }
}
